export const mnsuCourseCatalog = RAW_COURSES.split("\n").reduce((catalog, line) => {
  const [dept, code, name, creditsStr] = line.split("|");
  if (!dept || !code) return catalog;
  if (!catalog[dept]) catalog[dept] = [];
  const credits = creditsStr ? parseInt(creditsStr, 10) : null;
  if (!catalog[dept].some((c) => c.code === code)) {
    catalog[dept].push({ code, name, credits });
  }
  return catalog;
}, {});